package com.bank.onboarding;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TopoSortDemo {

    private static final Logger log = Logger.getLogger(TopoSortDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OnboardingPlanner planner = new OnboardingPlanner();

        // 4 steps: 0=open ledger, 1=post opening balance, 2=issue card, 3=activate
        // prereq [a,b] means a must come before b.
        int[][] prereqs = {{0, 1}, {0, 2}, {1, 3}, {2, 3}};

        List<Integer> order = planner.planOrder(4, prereqs);
        log.info(() -> "Valid onboarding order: " + order);  // [0,1,2,3]
    }
}

