class OnboardingPlanner {

    private static final Logger log = Logger.getLogger(OnboardingPlanner.class.getName());

    // Returns a valid order, or empty list if a cycle makes it impossible.
    java.util.List<Integer> planOrder(int n, int[][] prereqs) {
        java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new java.util.ArrayList<>());
        int[] inDegree = new int[n];

        for (int[] edge : prereqs) {
            adj.get(edge[0]).add(edge[1]);   // edge[0] before edge[1]
            inDegree[edge[1]]++;
        }

        // Seed queue with all zero-in-degree (no prerequisite) steps.
        java.util.Deque<Integer> queue = new java.util.ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (inDegree[i] == 0) queue.offer(i);
        }

        java.util.List<Integer> order = new java.util.ArrayList<>();
        while (!queue.isEmpty()) {
            int step = queue.poll();
            order.add(step);
            for (int next : adj.get(step)) {
                if (--inDegree[next] == 0) {  // freed up → schedulable
                    queue.offer(next);
                }
            }
        }

        if (order.size() != n) {
            log.severe("  cycle detected — no valid order exists");
            return java.util.List.of();
        }
        return order;
    }
}

